from .money import to_cents, cents_to_str


class Invoice:
    def __init__(self):
        self._items = []

    def add(self, description, price):
        self._items.append((description, price))

    def total_cents(self):
        total = sum(to_cents(price) for _, price in self._items)
        # Apply discount if set
        if hasattr(self, '_discount') and self._discount is not None:
            from .discount import apply_discount
            total = apply_discount(total, self._discount)
        return total

    def cents_to_str(self, cents):
        return cents_to_str(cents)

    def set_discount(self, percent):
        if not (0 <= percent <= 100):
            raise ValueError("Discount percent must be between 0 and 100 inclusive.")
        self._discount = percent
